(() => {
  const rows = [], failures = [], callbacks = [];
  const check = (name, actual, expected) => {
    rows.push([name, actual]);
    if (JSON.stringify(actual) !== JSON.stringify(expected)) failures.push(name);
  };
  const frame = document.createElement('iframe');
  frame.style.cssText = 'width:320px;height:100px;border:0';
  document.body.append(frame);
  const child = frame.contentWindow;
  child.document.open();
  child.document.write('<!doctype html><html style="overflow:hidden"><body style="margin:0"></body>');
  child.document.close();
  const viewport = child.visualViewport;
  const query = child.matchMedia('(min-width: 400px)');
  query.onchange = () => callbacks.push('media');
  viewport.onresize = () => callbacks.push('viewport');
  requestAnimationFrame(() => callbacks.push('frame'));
  // Establish an old canonical layout before each first dirty read.
  frame.getBoundingClientRect();
  check('initial', [query.matches, viewport.width, viewport.height], [false, 320, 100]);
  frame.style.width = '400px';
  check('retained-query', query.matches, true);
  frame.style.width = '420px';
  check('retained-width', viewport.width, 420);
  frame.style.height = '140px';
  check('retained-height', viewport.height, 140);
  frame.style.width = '380px';
  check('new-query', child.matchMedia('(max-width: 390px)').matches, true);
  frame.style.width = '440px';
  const widthGetter = Object.getOwnPropertyDescriptor(VisualViewport.prototype, 'width').get;
  check('borrowed-width', widthGetter.call(viewport), 440);
  const childWidthGetter = Object.getOwnPropertyDescriptor(child.VisualViewport.prototype, 'width').get;
  check('borrowed-root', childWidthGetter.call(visualViewport), visualViewport.width);
  const matchesGetter = Object.getOwnPropertyDescriptor(MediaQueryList.prototype, 'matches').get;
  frame.style.width = '360px';
  check('borrowed-query', matchesGetter.call(query), false);
  const nestedFrame = child.document.createElement('iframe');
  nestedFrame.style.cssText = 'width:50%;height:50px;border:0';
  child.document.body.append(nestedFrame);
  const nested = nestedFrame.contentWindow;
  nested.document.open();
  nested.document.write('<!doctype html><html style="overflow:hidden"><body style="margin:0"></body>');
  nested.document.close();
  const nestedQuery = nested.matchMedia('(min-width: 200px)');
  const nestedViewport = nested.visualViewport;
  frame.getBoundingClientRect();
  frame.style.width = '400px';
  check('nested-query', nestedQuery.matches, true);
  frame.style.width = '480px';
  check('nested-width', nestedViewport.width, 240);
  check('clean', [nestedViewport.width, query.matches, viewport.width], [240, true, 480]);
  frame.style.display = 'none';
  frame.style.width = '540px';
  frame.style.height = '180px';
  check('hidden', [viewport.width, viewport.height, query.matches], [480, 140, true]);
  frame.style.display = 'block';
  check('shown', [viewport.width, viewport.height, query.matches], [540, 180, true]);
  frame.remove();
  check('removed', [viewport.width, viewport.height, query.matches], [0, 0, false]);
  document.body.append(frame);
  check('reattached-old-objects', [viewport.width, viewport.height, query.matches], [0, 0, false]);
  check('synchronous-callbacks', callbacks, []);
  return {rows, failures};
})()
